package profilechannels

import (
	"crypto/sha256"
	"encoding/hex"
	"sort"
	"strings"

	"github.com/TrebuchetDynamics/gormes-agent/internal/config"
)

const (
	ProfileChannelEvidenceCredentialMissing         = "channel_credential_missing"
	ProfileChannelEvidenceCredentialKindMismatch    = "channel_credential_kind_mismatch"
	ProfileChannelEvidenceCredentialChannelMismatch = "channel_credential_channel_mismatch"
	ProfileChannelEvidenceCredentialOwnerMismatch   = "channel_credential_owner_mismatch"
	ProfileChannelEvidenceCredentialSecretMissing   = "channel_credential_secret_missing"
	ProfileChannelEvidenceCredentialHashUnavailable = "channel_credential_hash_unavailable"
	ProfileChannelEvidenceAccessPolicyMissing       = "channel_access_policy_missing"
	ProfileChannelEvidenceTokenHashConflict         = "channel_token_hash_conflict"
)

type ProfileChannelReadinessReport struct {
	Bindings []ProfileChannelBindingReadiness  `json:"bindings"`
	Evidence []ProfileChannelReadinessEvidence `json:"evidence,omitempty"`
}

type ProfileChannelReadinessOptions struct {
	CredentialHashes map[string]string
}

type ProfileChannelBindingReadiness struct {
	ProfileID              string                            `json:"profile_id"`
	Channel                string                            `json:"channel"`
	Ready                  bool                              `json:"ready"`
	CredentialID           string                            `json:"credential_id,omitempty"`
	CredentialOwnerProfile string                            `json:"credential_owner_profile,omitempty"`
	CredentialHash         string                            `json:"credential_hash,omitempty"`
	SecretRefConfigured    bool                              `json:"secret_ref_configured"`
	SecretRefSource        string                            `json:"secret_ref_source,omitempty"`
	AllowedChatCount       int                               `json:"allowed_chat_count"`
	AllowedChatScopeHash   string                            `json:"allowed_chat_scope_hash,omitempty"`
	AllowedDirectChatCount int                               `json:"allowed_direct_chat_count"`
	AllowedGroupChatCount  int                               `json:"allowed_group_chat_count"`
	AllowedUserCount       int                               `json:"allowed_user_count"`
	AllowedUserScopeHash   string                            `json:"allowed_user_scope_hash,omitempty"`
	RequireMention         bool                              `json:"require_mention"`
	ToolProgress           string                            `json:"tool_progress,omitempty"`
	ServerCount            int                               `json:"server_count,omitempty"`
	VoiceProfileSet        bool                              `json:"voice_profile_set,omitempty"`
	Evidence               []ProfileChannelReadinessEvidence `json:"evidence,omitempty"`
}

type ProfileChannelReadinessEvidence struct {
	Code           string `json:"code"`
	ProfileID      string `json:"profile_id,omitempty"`
	Channel        string `json:"channel,omitempty"`
	CredentialID   string `json:"credential_id,omitempty"`
	CredentialHash string `json:"credential_hash,omitempty"`
	Field          string `json:"field,omitempty"`
	Message        string `json:"message,omitempty"`
	Redacted       bool   `json:"redacted"`
}

func BuildProfileChannelReadiness(cfg config.Config) ProfileChannelReadinessReport {
	return BuildProfileChannelReadinessWithOptions(cfg, ProfileChannelReadinessOptions{})
}

func BuildProfileChannelReadinessWithOptions(cfg config.Config, opts ProfileChannelReadinessOptions) ProfileChannelReadinessReport {
	credentialHashes := NormalizedCredentialHashes(opts.CredentialHashes)
	var report ProfileChannelReadinessReport
	for _, service := range cfg.EnabledProfileServices() {
		channelConfigs := SortedConfigBindings(service.Profile.Channels)
		for _, channelConfig := range channelConfigs {
			if !channelConfig.Config.Enabled {
				continue
			}
			binding := buildProfileChannelBindingReadiness(cfg, service.ID, channelConfig.Channel, channelConfig.Config)
			if hash := credentialHashes[binding.CredentialID]; hash != "" {
				binding.CredentialHash = hash
			}
			report.Bindings = append(report.Bindings, binding)
		}
	}
	applyProfileChannelTokenHashConflicts(&report)
	report.Evidence = CollectReadinessEvidence(report.Bindings)
	return report
}

func buildProfileChannelBindingReadiness(cfg config.Config, profileID, channel string, channelCfg config.ProfileChannelCfg) ProfileChannelBindingReadiness {
	channel = strings.ToLower(strings.TrimSpace(channel))
	allowedChats := normalizedProfileChannelAllowList(channel, channelCfg.AllowedChats)
	allowedUsers := normalizedProfileChannelAllowedUsers(channel, channelCfg.AllowedUsers)
	allowedDirectChatCount, allowedGroupChatCount := profileChannelAllowedChatShapeCounts(channel, allowedChats)
	credentialID := strings.TrimSpace(channelCfg.Credential)
	binding := ProfileChannelBindingReadiness{
		ProfileID:              strings.TrimSpace(profileID),
		Channel:                channel,
		CredentialID:           credentialID,
		AllowedChatCount:       len(allowedChats),
		AllowedChatScopeHash:   profileChannelScopeHash("allowed_chats", allowedChats),
		AllowedDirectChatCount: allowedDirectChatCount,
		AllowedGroupChatCount:  allowedGroupChatCount,
		AllowedUserCount:       len(allowedUsers),
		AllowedUserScopeHash:   profileChannelScopeHash("allowed_users", allowedUsers),
		RequireMention:         channelCfg.RequireMention,
		ToolProgress:           strings.ToLower(strings.TrimSpace(channelCfg.ToolProgress)),
		ServerCount:            len(normalizedProfileChannelList(channelCfg.Servers)),
		VoiceProfileSet:        strings.TrimSpace(channelCfg.VoiceProfile) != "",
	}
	binding.Evidence = validateProfileChannelCredential(cfg, binding.ProfileID, binding.Channel, credentialID)
	binding.Evidence = append(binding.Evidence, validateProfileChannelAccessPolicy(binding.ProfileID, binding.Channel, credentialID, allowedChats, allowedUsers)...)
	if credentialID != "" {
		if credential, ok := cfg.Credentials[credentialID]; ok {
			binding.CredentialOwnerProfile = strings.TrimSpace(credential.OwnerProfile)
			if credential.SecretRef != nil {
				binding.SecretRefConfigured = true
				binding.SecretRefSource = strings.ToLower(strings.TrimSpace(string(credential.SecretRef.Source)))
			}
		}
	}
	binding.Ready = len(binding.Evidence) == 0
	return binding
}

func validateProfileChannelCredential(cfg config.Config, profileID, channel, credentialID string) []ProfileChannelReadinessEvidence {
	if credentialID == "" {
		return []ProfileChannelReadinessEvidence{NewEvidence(ProfileChannelEvidenceCredentialMissing, profileID, channel, credentialID, "credential", "profile channel has no credential id")}
	}
	credential, ok := cfg.Credentials[credentialID]
	if !ok {
		return []ProfileChannelReadinessEvidence{NewEvidence(ProfileChannelEvidenceCredentialMissing, profileID, channel, credentialID, "credential", "profile channel credential id is not defined")}
	}

	var evidence []ProfileChannelReadinessEvidence
	if kind := strings.ToLower(strings.TrimSpace(credential.Kind)); kind != "channel" {
		evidence = append(evidence, NewEvidence(ProfileChannelEvidenceCredentialKindMismatch, profileID, channel, credentialID, "kind", "credential kind must be channel"))
	}
	if credentialChannel := strings.ToLower(strings.TrimSpace(credential.Channel)); credentialChannel != "" && credentialChannel != channel {
		evidence = append(evidence, NewEvidence(ProfileChannelEvidenceCredentialChannelMismatch, profileID, channel, credentialID, "channel", "credential channel does not match profile channel"))
	}
	if ownerProfile := strings.TrimSpace(credential.OwnerProfile); ownerProfile != "" && ownerProfile != profileID {
		evidence = append(evidence, NewEvidence(ProfileChannelEvidenceCredentialOwnerMismatch, profileID, channel, credentialID, "owner_profile", "credential owner profile does not match profile channel"))
	}
	if credential.SecretRef == nil || strings.TrimSpace(credential.SecretRef.ID) == "" {
		evidence = append(evidence, NewEvidence(ProfileChannelEvidenceCredentialSecretMissing, profileID, channel, credentialID, "secret_ref", "channel credential has no secret ref"))
	}
	return evidence
}

func validateProfileChannelAccessPolicy(profileID, channel, credentialID string, allowedChats, allowedUsers []string) []ProfileChannelReadinessEvidence {
	if credentialID == "" || channel != "whatsapp" || len(allowedChats) > 0 || len(allowedUsers) > 0 {
		return nil
	}
	return []ProfileChannelReadinessEvidence{NewEvidence(ProfileChannelEvidenceAccessPolicyMissing, profileID, channel, credentialID, "allowed_chats", "profile channel has no WhatsApp chat or user allow-list")}
}

func applyProfileChannelTokenHashConflicts(report *ProfileChannelReadinessReport) {
	if report == nil || len(report.Bindings) < 2 {
		return
	}
	type conflictKey struct {
		channel string
		hash    string
	}
	buckets := map[conflictKey][]int{}
	for i := range report.Bindings {
		binding := &report.Bindings[i]
		binding.CredentialHash = normalizeProfileChannelCredentialHash(binding.CredentialHash)
		if binding.Channel == "" || binding.CredentialID == "" || binding.CredentialHash == "" {
			continue
		}
		key := conflictKey{channel: binding.Channel, hash: binding.CredentialHash}
		buckets[key] = append(buckets[key], i)
	}

	for _, indexes := range buckets {
		if len(indexes) < 2 {
			continue
		}
		credentialIDs := map[string]struct{}{}
		profileIDs := map[string]struct{}{}
		for _, index := range indexes {
			binding := report.Bindings[index]
			credentialIDs[binding.CredentialID] = struct{}{}
			profileIDs[binding.ProfileID] = struct{}{}
		}
		if len(credentialIDs) < 2 || len(profileIDs) < 2 {
			continue
		}
		for _, index := range indexes {
			binding := &report.Bindings[index]
			evidence := NewEvidence(ProfileChannelEvidenceTokenHashConflict, binding.ProfileID, binding.Channel, binding.CredentialID, "credential_hash", "credential token hash is already assigned to another profile-channel binding")
			evidence.CredentialHash = binding.CredentialHash
			binding.Evidence = append(binding.Evidence, evidence)
			binding.Ready = false
		}
	}
}

func CollectReadinessEvidence(bindings []ProfileChannelBindingReadiness) []ProfileChannelReadinessEvidence {
	var evidence []ProfileChannelReadinessEvidence
	for _, binding := range bindings {
		evidence = append(evidence, binding.Evidence...)
	}
	return evidence
}

func NormalizedCredentialHashes(in map[string]string) map[string]string {
	if len(in) == 0 {
		return nil
	}
	out := make(map[string]string, len(in))
	for credentialID, hash := range in {
		credentialID = strings.TrimSpace(credentialID)
		hash = normalizeProfileChannelCredentialHash(hash)
		if credentialID == "" || hash == "" {
			continue
		}
		out[credentialID] = hash
	}
	return out
}

func normalizeProfileChannelCredentialHash(hash string) string {
	return strings.ToLower(strings.TrimSpace(hash))
}

type ConfigBinding struct {
	Channel string
	Config  config.ProfileChannelCfg
}

func SortedConfigBindings(channels map[string]config.ProfileChannelCfg) []ConfigBinding {
	if len(channels) == 0 {
		return nil
	}
	type candidate struct {
		channel string
		rawKey  string
		config  config.ProfileChannelCfg
	}
	candidates := make([]candidate, 0, len(channels))
	for rawKey, channelConfig := range channels {
		channel := strings.ToLower(strings.TrimSpace(rawKey))
		if channel == "" {
			continue
		}
		candidates = append(candidates, candidate{channel: channel, rawKey: rawKey, config: channelConfig})
	}
	sort.Slice(candidates, func(i, j int) bool {
		if candidates[i].channel != candidates[j].channel {
			return candidates[i].channel < candidates[j].channel
		}
		iExact := candidates[i].rawKey == candidates[i].channel
		jExact := candidates[j].rawKey == candidates[j].channel
		if iExact != jExact {
			return iExact
		}
		return candidates[i].rawKey < candidates[j].rawKey
	})

	out := make([]ConfigBinding, 0, len(candidates))
	seen := map[string]struct{}{}
	for _, candidate := range candidates {
		if _, ok := seen[candidate.channel]; ok {
			continue
		}
		seen[candidate.channel] = struct{}{}
		out = append(out, ConfigBinding{Channel: candidate.channel, Config: candidate.config})
	}
	return out
}

func normalizedProfileChannelAllowList(channel string, values []string) []string {
	if strings.ToLower(strings.TrimSpace(channel)) != "whatsapp" {
		return normalizedProfileChannelList(values)
	}
	return normalizedProfileChannelListWithCanonicalizer(values, strings.ToLower)
}

func normalizedProfileChannelAllowedUsers(channel string, values []string) []string {
	if strings.ToLower(strings.TrimSpace(channel)) != "whatsapp" {
		return normalizedProfileChannelList(values)
	}
	return normalizedProfileChannelListWithCanonicalizer(values, canonicalProfileChannelWhatsAppUserID)
}

func canonicalProfileChannelWhatsAppUserID(value string) string {
	value = strings.TrimPrefix(strings.ToLower(strings.TrimSpace(value)), "+")
	if before, _, ok := strings.Cut(value, "@"); ok {
		value = before
	}
	if before, _, ok := strings.Cut(value, ":"); ok {
		value = before
	}
	return strings.TrimSpace(value)
}

func normalizedProfileChannelList(values []string) []string {
	return normalizedProfileChannelListWithCanonicalizer(values, func(value string) string { return value })
}

func normalizedProfileChannelListWithCanonicalizer(values []string, canonicalize func(string) string) []string {
	if len(values) == 0 {
		return nil
	}
	out := make([]string, 0, len(values))
	seen := map[string]struct{}{}
	for _, value := range values {
		value = strings.TrimSpace(value)
		if canonicalize != nil {
			value = canonicalize(value)
		}
		if value == "" {
			continue
		}
		if _, ok := seen[value]; ok {
			continue
		}
		seen[value] = struct{}{}
		out = append(out, value)
	}
	sort.Strings(out)
	return out
}

func profileChannelScopeHash(kind string, values []string) string {
	if len(values) == 0 {
		return ""
	}
	sum := sha256.Sum256([]byte(kind + "\x00" + strings.Join(values, "\x00")))
	return hex.EncodeToString(sum[:])
}

func profileChannelAllowedChatShapeCounts(channel string, allowedChats []string) (direct int, group int) {
	if strings.ToLower(strings.TrimSpace(channel)) != "whatsapp" {
		return 0, 0
	}
	for _, chat := range allowedChats {
		chat = strings.ToLower(strings.TrimSpace(chat))
		if chat == "" {
			continue
		}
		if strings.HasSuffix(chat, "@g.us") {
			group++
			continue
		}
		direct++
	}
	return direct, group
}

func NewEvidence(code, profileID, channel, credentialID, field, message string) ProfileChannelReadinessEvidence {
	return ProfileChannelReadinessEvidence{
		Code:         code,
		ProfileID:    profileID,
		Channel:      channel,
		CredentialID: credentialID,
		Field:        field,
		Message:      message,
		Redacted:     true,
	}
}

package profilechannels

import (
	"encoding/json"
	"strings"
	"testing"

	"github.com/TrebuchetDynamics/gormes-agent/internal/config"
	"github.com/TrebuchetDynamics/gormes-agent/internal/gateway/profilechanneltest"
)

func TestProfileChannelReadinessAllowsSameChannelDifferentProfileCredentialsAndAllowLists(t *testing.T) {
	cfg := config.Config{
		Profiles: map[string]config.ProfileCfg{
			"main": {
				Enabled: true,
				Channels: map[string]config.ProfileChannelCfg{
					"whatsapp": {
						Enabled:        true,
						Credential:     "main-whatsapp",
						AllowedChats:   []string{"12025550123@s.whatsapp.net"},
						AllowedUsers:   []string{"6586915095"},
						RequireMention: true,
						ToolProgress:   "compact",
					},
				},
			},
			"sales": {
				Enabled: true,
				Channels: map[string]config.ProfileChannelCfg{
					"whatsapp": {
						Enabled:      true,
						Credential:   "sales-whatsapp",
						AllowedChats: []string{"12025550999-123@g.us"},
						AllowedUsers: []string{"7770001111"},
					},
				},
			},
		},
		Credentials: map[string]config.CredentialCfg{
			"main-whatsapp": {
				Kind:         "channel",
				Channel:      "whatsapp",
				OwnerProfile: "main",
				SecretRef: &config.SecretRef{
					Source: config.SecretRefSourceEnv,
					ID:     "GORMES_MAIN_WHATSAPP_TOKEN",
				},
			},
			"sales-whatsapp": {
				Kind:         "channel",
				Channel:      "whatsapp",
				OwnerProfile: "sales",
				SecretRef: &config.SecretRef{
					Source: config.SecretRefSourceEnv,
					ID:     "GORMES_SALES_WHATSAPP_TOKEN",
				},
			},
		},
	}

	report := BuildProfileChannelReadiness(cfg)
	mainBinding := findProfileChannelBinding(t, report, "main", "whatsapp")
	salesBinding := findProfileChannelBinding(t, report, "sales", "whatsapp")
	if !mainBinding.Ready || !salesBinding.Ready {
		t.Fatalf("readiness = main:%+v sales:%+v, want both ready", mainBinding, salesBinding)
	}
	if mainBinding.CredentialID == salesBinding.CredentialID {
		t.Fatalf("credential IDs unexpectedly shared: main=%q sales=%q", mainBinding.CredentialID, salesBinding.CredentialID)
	}
	if mainBinding.AllowedChatCount != 1 || salesBinding.AllowedChatCount != 1 {
		t.Fatalf("allowed chat counts = main:%d sales:%d, want 1 each", mainBinding.AllowedChatCount, salesBinding.AllowedChatCount)
	}
	if mainBinding.AllowedChatScopeHash == "" || salesBinding.AllowedChatScopeHash == "" || mainBinding.AllowedChatScopeHash == salesBinding.AllowedChatScopeHash {
		t.Fatalf("allowed chat scope hashes = main:%q sales:%q, want non-empty distinct redacted scopes", mainBinding.AllowedChatScopeHash, salesBinding.AllowedChatScopeHash)
	}
	if mainBinding.AllowedUserScopeHash == "" || salesBinding.AllowedUserScopeHash == "" || mainBinding.AllowedUserScopeHash == salesBinding.AllowedUserScopeHash {
		t.Fatalf("allowed user scope hashes = main:%q sales:%q, want non-empty distinct redacted scopes", mainBinding.AllowedUserScopeHash, salesBinding.AllowedUserScopeHash)
	}
	if !mainBinding.SecretRefConfigured || mainBinding.SecretRefSource != "env" {
		t.Fatalf("main secret ref readiness = configured:%v source:%q, want configured env", mainBinding.SecretRefConfigured, mainBinding.SecretRefSource)
	}

	body, err := json.Marshal(report)
	if err != nil {
		t.Fatalf("marshal readiness report: %v", err)
	}
	for _, leaked := range []string{
		"12025550123", "12025550999", "6586915095", "7770001111",
		"GORMES_MAIN_WHATSAPP_TOKEN", "GORMES_SALES_WHATSAPP_TOKEN",
	} {
		if strings.Contains(string(body), leaked) {
			t.Fatalf("readiness report leaked sensitive value %q:\n%s", leaked, body)
		}
	}
}

func TestProfileChannelReadinessWhatsAppAllowListsCanonicalizeJIDCase(t *testing.T) {
	cfg := config.Config{
		Profiles: map[string]config.ProfileCfg{
			"main": {
				Enabled: true,
				Channels: map[string]config.ProfileChannelCfg{
					"whatsapp": {
						Enabled:    true,
						Credential: "main-whatsapp",
						AllowedChats: []string{
							"12025550123@S.WHATSAPP.NET",
							"12025550123@s.whatsapp.net",
							"12025550999-123@G.US",
							"12025550999-123@g.us",
						},
						AllowedUsers: []string{"6586915095", " 6586915095 "},
					},
				},
			},
		},
		Credentials: map[string]config.CredentialCfg{
			"main-whatsapp": profilechanneltest.ChannelCredential("whatsapp", "main", "GORMES_MAIN_WHATSAPP_TOKEN"),
		},
	}

	report := BuildProfileChannelReadiness(cfg)
	binding := findProfileChannelBinding(t, report, "main", "whatsapp")
	if !binding.Ready {
		t.Fatalf("binding Ready = false, want ready after canonicalizing duplicated WhatsApp JID case: %+v", binding)
	}
	if binding.AllowedChatCount != 2 || binding.AllowedDirectChatCount != 1 || binding.AllowedGroupChatCount != 1 {
		t.Fatalf("chat counts = total:%d direct:%d group:%d, want 2/1/1 after case canonicalization", binding.AllowedChatCount, binding.AllowedDirectChatCount, binding.AllowedGroupChatCount)
	}
	if binding.AllowedUserCount != 1 {
		t.Fatalf("AllowedUserCount = %d, want duplicate trimmed user collapsed", binding.AllowedUserCount)
	}

	body, err := json.Marshal(report)
	if err != nil {
		t.Fatalf("marshal readiness report: %v", err)
	}
	for _, leaked := range []string{"12025550123", "12025550999", "6586915095", "GORMES_MAIN_WHATSAPP_TOKEN"} {
		if strings.Contains(string(body), leaked) {
			t.Fatalf("readiness report leaked sensitive value %q:\n%s", leaked, body)
		}
	}
}

func TestProfileChannelReadinessMissingCredentialSkipsOnlyThatBinding(t *testing.T) {
	cfg := config.Config{
		Profiles: map[string]config.ProfileCfg{
			"main": {
				Enabled: true,
				Channels: map[string]config.ProfileChannelCfg{
					"whatsapp": {Enabled: true, Credential: "missing-whatsapp"},
				},
			},
			"ops": {
				Enabled: true,
				Channels: map[string]config.ProfileChannelCfg{
					"telegram": {Enabled: true, Credential: "ops-telegram", AllowedUsers: []string{"42"}},
				},
			},
		},
		Credentials: map[string]config.CredentialCfg{
			"ops-telegram": {
				Kind:         "channel",
				Channel:      "telegram",
				OwnerProfile: "ops",
				SecretRef: &config.SecretRef{
					Source: config.SecretRefSourceEnv,
					ID:     "GORMES_OPS_TELEGRAM_TOKEN",
				},
			},
		},
	}

	report := BuildProfileChannelReadiness(cfg)
	missing := findProfileChannelBinding(t, report, "main", "whatsapp")
	ready := findProfileChannelBinding(t, report, "ops", "telegram")
	if missing.Ready {
		t.Fatalf("missing binding Ready = true, want skipped/degraded: %+v", missing)
	}
	if !HasEvidenceCode(missing.Evidence, "channel_credential_missing") {
		t.Fatalf("missing binding evidence = %+v, want channel_credential_missing", missing.Evidence)
	}
	if !ready.Ready {
		t.Fatalf("unrelated binding Ready = false, want available despite missing WhatsApp credential: %+v", ready)
	}
	if len(report.Bindings) != 2 {
		t.Fatalf("bindings = %d, want both degraded and ready bindings present", len(report.Bindings))
	}
}

func TestProfileChannelReadinessDuplicateTokenHashConflictsAcrossProfiles(t *testing.T) {
	const rawSharedToken = "123456:shared-whatsapp-token-that-must-not-leak"
	sharedHash := profilechanneltest.TokenCredentialHash(rawSharedToken)
	cfg := config.Config{
		Profiles: map[string]config.ProfileCfg{
			"main": {
				Enabled: true,
				Channels: map[string]config.ProfileChannelCfg{
					"whatsapp": {Enabled: true, Credential: "main-whatsapp"},
				},
			},
			"sales": {
				Enabled: true,
				Channels: map[string]config.ProfileChannelCfg{
					"whatsapp": {Enabled: true, Credential: "sales-whatsapp"},
				},
			},
			"ops": {
				Enabled: true,
				Channels: map[string]config.ProfileChannelCfg{
					"telegram": {Enabled: true, Credential: "ops-telegram"},
				},
			},
		},
		Credentials: map[string]config.CredentialCfg{
			"main-whatsapp":  profilechanneltest.ChannelCredential("whatsapp", "main", "GORMES_MAIN_WHATSAPP_TOKEN"),
			"sales-whatsapp": profilechanneltest.ChannelCredential("whatsapp", "sales", "GORMES_SALES_WHATSAPP_TOKEN"),
			"ops-telegram":   profilechanneltest.ChannelCredential("telegram", "ops", "GORMES_OPS_TELEGRAM_TOKEN"),
		},
	}

	report := BuildProfileChannelReadinessWithOptions(cfg, ProfileChannelReadinessOptions{
		CredentialHashes: map[string]string{
			"main-whatsapp":  sharedHash,
			"sales-whatsapp": sharedHash,
			"ops-telegram":   profilechanneltest.TokenCredentialHash("other-token"),
		},
	})
	mainBinding := findProfileChannelBinding(t, report, "main", "whatsapp")
	salesBinding := findProfileChannelBinding(t, report, "sales", "whatsapp")
	opsBinding := findProfileChannelBinding(t, report, "ops", "telegram")
	for _, binding := range []ProfileChannelBindingReadiness{mainBinding, salesBinding} {
		if binding.Ready {
			t.Fatalf("%s binding Ready = true, want token ownership conflict evidence: %+v", binding.ProfileID, binding)
		}
		if binding.CredentialHash != sharedHash {
			t.Fatalf("%s credential hash = %q, want shared hash %q", binding.ProfileID, binding.CredentialHash, sharedHash)
		}
		if !HasEvidenceCode(binding.Evidence, "channel_token_hash_conflict") {
			t.Fatalf("%s evidence = %+v, want channel_token_hash_conflict", binding.ProfileID, binding.Evidence)
		}
	}
	if !opsBinding.Ready {
		t.Fatalf("unrelated telegram binding Ready = false, want ready: %+v", opsBinding)
	}

	body, err := json.Marshal(report)
	if err != nil {
		t.Fatalf("marshal readiness report: %v", err)
	}
	for _, leaked := range []string{
		rawSharedToken, "shared-whatsapp-token", "GORMES_MAIN_WHATSAPP_TOKEN", "GORMES_SALES_WHATSAPP_TOKEN",
	} {
		if strings.Contains(string(body), leaked) {
			t.Fatalf("readiness report leaked sensitive value %q:\n%s", leaked, body)
		}
	}
}

func findProfileChannelBinding(t *testing.T, report ProfileChannelReadinessReport, profileID, channel string) ProfileChannelBindingReadiness {
	t.Helper()
	for _, binding := range report.Bindings {
		if binding.ProfileID == profileID && binding.Channel == channel {
			return binding
		}
	}
	t.Fatalf("missing profile channel binding profile=%q channel=%q in %+v", profileID, channel, report.Bindings)
	return ProfileChannelBindingReadiness{}
}

package profilechannels

func HasEvidenceCode(items []ProfileChannelReadinessEvidence, code string) bool {
	for _, item := range items {
		if item.Code == code {
			return true
		}
	}
	return false
}

package profilechannels

import "testing"

func TestHasEvidenceCode(t *testing.T) {
	items := []ProfileChannelReadinessEvidence{{Code: "missing"}, {Code: "ready"}}
	if !HasEvidenceCode(items, "ready") {
		t.Fatal("HasEvidenceCode missing ready evidence")
	}
	if HasEvidenceCode(items, "other") {
		t.Fatal("HasEvidenceCode returned true for absent evidence")
	}
}

